import {decide,decisionDefaults,validConditions,loadDecision,saveDecision,DECISION_KEY} from './decision.js';
import {decisionEntry,decisionPageHTML} from './decision-ui.js';
import {patchHTML, patchChildren} from './view.js';
import {icon} from './icons.js';
import {meals,shops,modes,residences,tastes,photoAlts,getMeal,getShop} from './data.js';
import {quote,eta,load,save,seed,defaultPrefs,selectMeals} from './model.js';
let state=load(), filters={...state.prefs}, compare=[], scenario='', query='', sort='smart', kind='all', orderTab='all', discoverTaste='all';
let homeLimit=8,discoverLimit=12;
let draft=null, sheetState=null, lastFocus=null, toastTimer=null, submitting=false;
try{draft=JSON.parse(sessionStorage.getItem('zhedun-draft'));}catch{}
if(draft&&(!getMeal(draft.mealId)||!getMeal(draft.mealId).modes.includes(draft.mode)||!Number.isInteger(draft.qty)||draft.qty<1||draft.qty>5||!['standard','large'].includes(draft.size)))draft=null;
let app=document.querySelector('#app'),nav=document.querySelector('#bottom-nav'),dock=document.querySelector('#compare-dock');
let renderedPath=null;
let decisionSession=null;
function decisionStorage(){try{return sessionStorage;}catch{return null;}}
function rememberDecision(){if(!saveDecision(decisionStorage(),decisionSession))toast('浏览器存储不可用，选择仅在当前页面保留');}
function ensureDecision(){if(!decisionSession){decisionSession=loadDecision(decisionStorage(),filters);saveDecision(decisionStorage(),decisionSession);}return decisionSession;}
function decisionPage(){navRender('home');const session=ensureDecision();const result=session.complete?decide(session.conditions):null;app.innerHTML=topbar('这顿帮你定')+decisionPageHTML(session,result);}
function decisionRefresh(){rememberDecision();render();const heading=$('#decision-heading');heading?.focus({preventScroll:true});heading?.scrollIntoView({block:'start',behavior:'instant'});}

const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>Number(n).toFixed(Number(n)%1?1:0);
const act=(action,attrs='')=>`data-action="${action}" ${attrs}`;
const badge=(text,red=false)=>`<span class="tag ${red?'red':''}">${esc(text)}</span>`;
const date=t=>new Date(t).toLocaleDateString('zh-CN',{month:'numeric',day:'numeric'});
const modeIcon=m=>({dine:'utensils',pickup:'bag',cabinet:'cabinet',delivery:'truck'}[m]||'bag');
const currentMode=()=>filters.mode==='all'?(scenario==='dorm'?'delivery':'pickup'):filters.mode;
const photo=(m,cls='',eager=false)=>`<img class="${cls}" src="assets/${m.image}.webp" alt="${photoAlts[m.image]||m.name}，同类餐食示意图" ${eager?'fetchpriority="high"':'loading="lazy"'} width="640" height="640">`;
const empty=(title,desc,action='home',button='去看看今天吃什么',glyph='bowl')=>`<div class="empty"><div class="empty-graphic">${icon(glyph)}</div><h2>${title}</h2><p>${desc}</p><button class="primary" ${act(action)}>${button}</button></div>`;
function persist(){if(!save(state))toast('浏览器存储不可用，本次操作仅在当前页面保留');}
function saveDraft(){try{sessionStorage.setItem('zhedun-draft',JSON.stringify(draft));}catch{}}
function toast(text){clearTimeout(toastTimer);const el=$('#toast');el.textContent=text;el.classList.add('show');toastTimer=setTimeout(()=>el.classList.remove('show'),2600);}
function go(path){closeSheet();if(location.hash==='#'+path)render();else location.hash=path;}
function back(){if(history.length>1)history.back();else go('/');}
function topbar(title,right=''){return `<header class="topbar"><button class="icon-btn" aria-label="返回" ${act('back')}>${icon('back')}</button><h1>${title}</h1><div class="side">${right}</div></header>`;}
function bottomAction(price,label,action,extra=''){nav.className='';nav.innerHTML=`<div class="bottom-action"><div>${extra}<strong class="price"><small>¥</small>${money(price)}</strong></div><button class="primary" ${act(action)}>${label}${icon('arrow','sm')}</button></div>`;}
function navRender(tab){nav.className='bottom-nav';nav.innerHTML=[['home','bowl','今天吃什么','/'],['discover','discover','发现','/discover'],['orders','order','订单','/orders'],['mine','user','我的','/mine']].map(([key,glyph,label,url])=>`<a class="nav-item ${tab===key?'active':''}" href="#${url}" ${tab===key?'aria-current="page"':''}>${icon(glyph)}<span>${label}</span></a>`).join('');}
function dockRender(visible=true){dock.innerHTML=compare.length&&visible?`<div class="compare-dock"><div><strong>已选 ${compare.length} / 3 份餐食</strong><br><small>价格、分量和时间，一起算清楚</small></div><div><button class="dock-clear" ${act('clear-compare')}>清空</button><button class="primary" ${act('go','data-path="/compare"')}>比一比${icon('compare','sm')}</button></div></div>`:'';$('#shell').classList.toggle('has-dock',!!(compare.length&&visible));}
function card(m){const s=getShop(m.shopId),mode=m.modes.includes(currentMode())?currentMode():'pickup',q=quote(m,mode);return `<article class="meal-card"><a href="#/meal/${m.id}" class="meal-photo" style="display:block"><span class="photo-badge">${m.sold?'今日售罄':esc(m.tag)}</span>${photo(m)}<span class="photo-note">同类示意图</span></a><a href="#/meal/${m.id}"><h3>${m.name}</h3></a><p class="meal-shop">${s.name}</p><div class="meal-meta">${icon('clock','sm')}约 ${eta(m,mode,filters.weather)} 分钟 <span>·</span> ${m.taste}</div><div class="meal-bottom"><div><span class="price"><small>¥</small>${money(q.total)}</span><span class="price-sub"> 到手</span></div><button class="compare-add ${compare.includes(m.id)?'selected':''}" aria-label="${compare.includes(m.id)?'移出比较':'加入比较'}：${m.name}" ${act('compare',`data-id="${m.id}"`)}>${icon(compare.includes(m.id)?'check':'plus')}</button></div></article>`;}
function conditions(){return `<div class="conditions"><button class="chip" ${act('filter')}>${icon('wallet','sm')}¥${filters.budget}以内${icon('down','sm')}</button><button class="chip" ${act('filter')}>${icon('clock','sm')}${filters.minutes}分钟内${icon('down','sm')}</button><button class="chip" ${act('filter')}>${icon(modeIcon(currentMode()),'sm')}${filters.mode==='all'?'不限方式':modes[filters.mode]}${icon('down','sm')}</button>${filters.taste!=='all'?`<button class="chip green" ${act('filter')}>${icon('utensils','sm')}${esc(filters.taste)}</button>`:''}${filters.energy==='low'?`<button class="chip green" ${act('filter')}>${icon('home','sm')}想少折腾</button>`:''}</div>`;}
function moreMeals(list,limit,action){return `<div class="menu-progress"><p>已展示 ${Math.min(limit,list.length)} / ${list.length} 道餐食</p>${limit<list.length?`<button class="secondary full" ${act(action)}>继续看，还有 ${list.length-limit} 道${icon('down','sm')}</button>`:'<span class="micro">这次筛选的餐食都在这里了</span>'}</div>`;}
function previewMatches(){const p={...sheetState.work};if(p.energy==='low'&&p.mode==='all')p.mode='delivery';const searching=app.dataset.route==='search';return selectMeals(meals,p,{q:searching?query:'',sort}).filter(m=>!searching||kind==='all'||getShop(m.shopId).type===kind);}
function updateFilterCount(){const list=previewMatches();const label=$('#filter-match-count'),count=$('#filter-apply-count');if(label)label.textContent=`匹配 ${list.length} 道 · 可预约 ${list.filter(m=>!m.sold).length} 道`;if(count)count.textContent=`（${list.length} 道）`;}
function home(){navRender('home');const list=selectMeals(meals,filters,{sort,scenario});const hero=list.find(m=>m.id==='m1'&&!m.sold)||list.find(m=>!m.sold);const heroMode=currentMode();app.innerHTML=`<div class="page"><header class="header-main"><a class="brand" href="#/" aria-label="这顿首页"><img src="assets/logo.svg" alt=""><div class="brand-stack"><b>这顿</b><br><small>ZHEDUN · CAMPUS TABLE</small></div></a><button class="campus" aria-label="选择住宿区域，当前：${esc(state.prefs.campus)}" aria-haspopup="dialog" title="${esc(state.prefs.campus)}" ${act('campus')}>${icon('pin','sm')}<span class="campus-label"><span>中国传媒大学</span><strong>${esc(state.prefs.campus.replace('中国传媒大学',''))}</strong></span>${icon('down','sm')}</button></header><div class="hello-row"><h1 class="home-title">忙归忙，<br>这顿<span> </span><em>好好吃。</em></h1><button class="weather" ${act('weather')} aria-label="切换天气情境">${icon(filters.weather==='rain'?'rain':'sun')}<span>${filters.weather==='rain'?'雨天 · 少跑腿':'晴天 · 去吃饭'}</span></button></div><button class="searchbox" ${act('go','data-path="/search"')}>${icon('search')}<span>想吃什么？搜菜名、食堂、口味</span></button>${hero?`<a href="#/meal/${hero.id}" class="hero" style="display:block">${photo(hero,'',true)}<span class="hero-top">今日<br>饭票</span><div class="hero-copy"><span class="label">这顿推荐 / ${getShop(hero.shopId).name}</span><h2>${hero.id==='m1'?'一锅热饭，刚好接住你。':hero.name}</h2><p>${hero.id==='m1'?hero.name:hero.tag} · ${modes[heroMode]}</p><div class="hero-action"><span class="hero-price"><small>¥</small>${money(quote(hero,heroMode).total)} <small>${modes[heroMode]}到手价</small></span><span class="circle-arrow">${icon('arrow')}</span></div></div></a>`:''}<div class="section-head"><div><h2>这顿，听你的</h2><p>今天什么状态，就怎么安排</p></div><button class="text-link" ${act('filter')}>自己选${icon('filter','sm')}</button></div><div class="scenario-grid">${[['rush','clock','赶时间'],['save','wallet','想省钱'],['dorm','home','留在宿舍'],['new','discover','想尝新']].map(([key,glyph,label])=>`<button class="scenario ${scenario===key?'active':''}" ${act('scenario',`data-value="${key}"`)}>${icon(glyph)}<span>${label}</span></button>`).join('')}</div>${decisionEntry()}${conditions()}<div class="ticket-note">${icon('ticket')}<div><strong>${scenario==='rush'?'把午休留给休息，取餐时间先安排好':scenario==='save'?'餐费、包装、配送都算上，才是到手价':scenario==='dorm'?'今天不出门，也想吃一口热乎饭':scenario==='new'?'尝新前，先看看口味和分量':'时间、分量、到手价，都替你摆明白'}</strong><small>${filters.weather==='rain'?'雨天情境：配送预计时间增加 5 分钟':'所有等待时间均为样品估计，支持预约自取'} · 饭点 ${esc(state.prefs.usual)}，记得提前约</small></div></div><div class="section-head"><div><h2>${scenario==='new'?'换个口味，也挺好':'给这顿一点灵感'}</h2><p>按你的条件找到 ${list.length} 道餐食</p></div><button class="text-link" ${act('go','data-path="/search"')}>全部菜单${icon('chevron','sm')}</button></div>${list.length?`<div class="meal-grid">${list.slice(0,homeLimit).map(card).join('')}</div>${moreMeals(list,homeLimit,'home-more')}`:empty('这会儿还没找到合适的饭','试试增加一点预算或可用时间','reset-filter','放宽条件')}<p class="footnote">好好吃饭，是每天的小正事</p><p class="micro" style="text-align:center">前端体验样品 · 模拟商家与菜单 · 不产生真实交易</p></div>`;}
function searchPage(){navRender('home');let list=selectMeals(meals,filters,{q:query,sort,scenario}).filter(m=>kind==='all'||getShop(m.shopId).type===kind);app.innerHTML=topbar('找一顿合适的饭')+`<div class="page narrow search-page"><form id="search-form" class="searchbox">${icon('search')}<input name="q" aria-label="搜索菜品或商家" placeholder="搜菜名、食堂、口味" value="${esc(query)}"><button type="submit" class="text-link">搜索</button></form><div class="choices">${[['all','全部'],['canteen','食堂窗口'],['takeaway','校外外卖']].map(([key,label])=>`<button class="choice ${kind===key?'active':''}" ${act('kind',`data-value="${key}"`)}>${label}</button>`).join('')}</div>${conditions()}<div class="sortbar"><span>共 ${list.length} 份餐食</span><label>排序 <select id="sort" aria-label="餐食排序"><option value="smart" ${sort==='smart'?'selected':''}>适合我的</option><option value="price" ${sort==='price'?'selected':''}>到手价优先</option><option value="time" ${sort==='time'?'selected':''}>吃得快优先</option></select></label></div>${list.length?`<div class="meal-grid">${list.map(card).join('')}</div>`:empty('换个条件，再找找','可以试试“牛腩”“清淡”，或放宽预算与时间','reset-search','重置搜索条件','search')}</div>`;}
function feeLines(q){return `<div class="fee-line"><span>餐食小计</span><span>¥${money(q.goods)}</span></div><div class="fee-line"><span>包装费</span><span>¥${money(q.pack)}</span></div><div class="fee-line"><span>配送费</span><span>¥${money(q.delivery)}</span></div>${q.discount?`<div class="fee-line discount"><span>餐食满 30 减 3（模拟）</span><span>−¥${money(q.discount)}</span></div>`:''}<div class="fee-line fee-total"><span>到手总价</span><span class="price"><small>¥</small>${money(q.total)}</span></div>`;}
function mealPage(id){const m=getMeal(id);if(!m)return notFound();const context=new URLSearchParams(location.hash.split('?')[1]||'');const chosen=context.get('mode')||currentMode();const weather=['sun','rain'].includes(context.get('weather'))?context.get('weather'):filters.weather;const s=getShop(m.shopId),mode=m.modes.includes(chosen)?chosen:m.modes[0],q=quote(m,mode);nav.innerHTML='';nav.className='';app.innerHTML=`<div class="detail-hero">${photo(m,'',true)}<div class="floating-bar"><button class="icon-btn soft" aria-label="返回" ${act('back')}>${icon('back')}</button><button class="icon-btn soft ${state.favorites.includes(id)?'favorited':''}" aria-label="${state.favorites.includes(id)?'取消收藏':'收藏餐食'}" ${act('favorite',`data-id="${id}"`)}>${icon('heart')}</button></div><span class="photo-note">AI 生成同类餐食示意图，非实际商家出品</span></div><div class="detail-body"><div class="row between"><span class="eyebrow">${s.type==='canteen'?'CAMPUS KITCHEN / 校园小灶':'NEIGHBORHOOD / 校外好味'}</span><span class="micro">${icon('star','sm')} ${m.rating} · 示例评分</span></div><h1 class="detail-title spaced">${m.name}</h1><div class="tags">${badge(m.tag,true)}${badge(m.taste)}${badge(m.portion.split(' · ')[1])}</div><p class="detail-desc">${m.desc}</p><div class="detail-metrics"><div class="metric"><strong>${eta(m,mode,weather)}<small> 分钟</small></strong>预计吃上饭</div><div class="metric"><strong>${m.portion.split(' · ')[0].replace('约 ','')}</strong>分量参考</div><div class="metric"><strong>${s.walk}<small> 分钟</small></strong>示例步行时间</div></div><button class="shop-row" ${act('go',`data-path="/shop/${s.id}"`)}><span class="shop-icon">${icon('shop')}</span><span><strong>${s.name}</strong><p>${s.place}</p></span>${icon('chevron','chev sm')}</button><div class="panel"><h3>这份饭，怎么到你手里</h3><div class="tags">${m.modes.map(x=>badge(modes[x])).join('')}</div><p class="detail-desc">${s.keep}。来源信息：${s.type==='canteen'?'校内合作窗口示例':'周边商家示例'}，不代表实际食品安全认证。</p><button class="text-link spaced" ${act('compare',`data-id="${id}"`)}>${icon('compare','sm')}${compare.includes(id)?'已加入比较，点击移出':'和别的餐食比一比'}</button></div><div class="panel"><h3>${modes[mode]} · 费用先看清</h3>${feeLines(q)}<p class="micro spaced">当前按标准份 1 份计算，规格与用餐方式可在下单前调整。</p></div><div class="section-head"><h2>同学怎么说</h2><span class="micro">示例评价</span></div>${reviewsHTML(id)}<div class="notice spaced">${icon('info')}<span>分量、口味和图片均为演示参考。食品安全及营养情况不能仅凭图片判断。</span></div></div>`;bottomAction(q.total,m.sold?'今日售罄 · 看其他餐':'选规格 · 约这顿',m.sold?'sold':'spec',`<small>${modes[mode]}到手价</small>`);Object.assign(nav.querySelector('[data-action]').dataset,{id,mode,weather});}
function reviewsHTML(id){const real=state.reviews.filter(r=>r.mealId===id);return [...real.map(r=>({name:'我',text:r.text||'这顿吃得挺满意。',stars:r.rating})),{name:'同学小林（示例）',text:'分量一人吃刚好，打包拿走也方便。下次还会考虑这一份。',stars:5},{name:'校园饭友（示例）',text:'口味偏家常，建议按自己平时的食量选标准份或加量份。',stars:4}].map(r=>`<div class="review-item"><div class="review-name"><span>${r.name}</span><span class="stars">${Array.from({length:r.stars},()=>icon('star')).join('')}</span></div><p>${esc(r.text)}</p></div>`).join('');}
function shopPage(id){const s=getShop(id);if(!s)return notFound();navRender('home');app.innerHTML=topbar('窗口与菜单')+`<div class="shop-cover"><span class="eyebrow" style="color:#e5d3a3">${s.type==='canteen'?'校园窗口 / WINDOW':'周边好店 / NEIGHBOR'}</span><div class="window-no">${s.no}</div><h1>${s.name}</h1><p>${s.desc}</p><div class="tags">${badge(s.type==='canteen'?'食堂窗口':'校外商家')}${badge('预约时段见下单页')}</div></div><div class="page"><div class="notice green">${icon('pin')}<span>${s.place}<br>示例营业：07:00–24:00 · 菜单与接单能力为模拟</span></div><div class="section-head"><h2>窗口里的好饭</h2><span class="micro">${s.keep}</span></div><div class="meal-grid">${meals.filter(m=>m.shopId===id).map(card).join('')}</div></div>`;}
function comparePage(){navRender('home');const selected=compare.map(getMeal).filter(Boolean);app.innerHTML=topbar('这顿，比明白再决定')+`<div class="page narrow"><p class="subtitle">同一种用餐方式下，价格和时间一起看。</p><div class="choices">${['pickup','delivery','dine','cabinet'].map(mode=>`<button class="choice ${currentMode()===mode?'active':''}" ${act('compare-mode',`data-value="${mode}"`)}>${modes[mode]}</button>`).join('')}</div>${selected.length?`<div class="compare-grid spaced" style="--cols:${selected.length}">${selected.map(m=>{const s=getShop(m.shopId),mode=currentMode(),supported=m.modes.includes(mode),q=quote(m,mode);return `<article class="compare-column">${photo(m)}<h3>${m.name}</h3><div class="compare-cell"><small>到手总价</small><strong class="price">${supported?'¥'+money(q.total):'—'}</strong></div><div class="compare-cell"><small>费用明细</small>${supported?`餐 ¥${m.price}<br>包装 ¥${q.pack} / 配送 ¥${q.delivery}`:'不支持此方式'}</div><div class="compare-cell"><small>分量参考</small>${m.portion}</div><div class="compare-cell"><small>预计吃上饭</small>${supported?'约 '+eta(m,mode,filters.weather)+' 分钟':'—'}</div><div class="compare-cell"><small>制作 / 步行</small>${m.prep} 分 / ${s.walk} 分</div><div class="compare-cell"><small>口味 / 获取方式</small>${m.taste}<br>${modes[mode]}</div><button class="primary" ${act('spec',`data-id="${m.id}" data-mode="${mode}"`)} ${!supported||m.sold?'disabled':''}>${m.sold?'已售罄':supported?'就吃这份':'不支持'}</button><button class="text-link" style="margin:0 auto 12px" ${act('compare',`data-id="${m.id}"`)}>移出比较</button></article>`;}).join('')}</div><div class="notice spaced">${icon('info')}<span>时间均为模拟估算。步行与制作可部分重叠，本样品采用相加方式保守估计；配送已包含送达时间。</span></div>`:empty('先挑两份，再比一比','点餐食卡片上的加号加入比较，最多三份。','home','去选餐','compare')}</div>`;}
function discover(){navRender('discover');let list=meals.filter(m=>!m.sold&&(discoverTaste==='all'||m.taste===discoverTaste));if(discoverTaste==='all')list=[...list.filter(m=>m.newArrival),...list.filter(m=>m.fresh&&!m.newArrival),...list.filter(m=>!m.fresh&&!m.newArrival)];app.innerHTML=`<div class="discover-head"><span class="eyebrow">THE CAMPUS TASTE JOURNAL</span><h1>熟悉的日子，<br>换一口新鲜。</h1><p>跟着口味走，尝新也心里有数。</p><span class="decor">${icon('utensils')}</span></div><div class="page narrow"><div class="editorial">${icon('leaf')}<div><h3>好不好吃，先看具体的</h3><p>分量、辣度、打包口感，比一个分数更懂你。</p></div></div><div class="choices">${['all',...tastes].map(t=>`<button class="choice ${discoverTaste===t?'active':''}" ${act('discover-taste',`data-value="${t}"`)}>${t==='all'?'都想看看':t}</button>`).join('')}</div><div class="section-head"><h2>${discoverTaste==='all'?'尝新清单':'这一口'+discoverTaste}</h2><span class="micro">示例口味推荐</span></div><div class="meal-grid">${list.slice(0,discoverLimit).map(card).join('')}</div>${moreMeals(list,discoverLimit,'discover-more')}<p class="footnote">饭可以常吃，口味可以常换</p></div>`;}
const statusText=o=>o.delayed&&o.status!=='done'&&o.status!=='cancelled'?'稍有延误':({placed:'预约已确认',preparing:'正在制作',ready:'可以取餐了',delivering:'正在配送',done:'已完成',cancelled:'已取消'}[o.status]);
function ordersPage(){navRender('orders');const list=state.orders.filter(o=>orderTab==='all'||(orderTab==='active'&&!['done','cancelled'].includes(o.status))||o.status===orderTab);app.innerHTML=topbar('我的这几顿')+`<div class="page narrow"><p class="subtitle">饭的去向，随时心里有数。</p><div class="order-tabs">${[['all','全部'],['active','进行中'],['done','已完成'],['cancelled','已取消']].map(([key,label])=>`<button class="chip ${orderTab===key?'active':''}" ${act('order-tab',`data-value="${key}"`)}>${label}</button>`).join('')}</div>${list.length?list.map(o=>{const m=getMeal(o.mealId);return `<article class="order-card"><a class="order-card-head" href="#/order/${o.id}"><strong>${getShop(m.shopId).name}</strong><span class="status ${o.delayed?'red':''}">${statusText(o)} ${icon('chevron','sm')}</span></a><a class="checkout-meal" href="#/order/${o.id}">${photo(m)}<div><h3>${esc(o.name)}</h3><p>${modes[o.mode]} · ${esc(o.slot)}</p><p>${o.qty} 份 · ${date(o.created)}</p></div><strong style="margin-left:auto;white-space:nowrap">¥${money(o.quote.total)}</strong></a><div class="order-card-actions">${o.status==='done'?`<button class="secondary" ${act('review',`data-id="${o.id}"`)}>${o.rated?'查看评价':'评价这顿'}</button><button class="primary" ${act('spec',`data-id="${o.mealId}"`)}>再吃一次</button>`:`<button class="${o.status==='ready'?'primary':'secondary'}" ${act('go',`data-path="/${o.status==='ready'?'voucher':'order'}/${o.id}"`)}>${o.status==='ready'?'出示取餐码':'查看详情'}</button>`}</div></article>`;}).join(''):empty('这里还没有这一类订单','去选一顿喜欢的饭，体验一次预约吧。')}</div>`;}
function checkout(){if(!draft||!getMeal(draft.mealId))return missingDraft();const m=getMeal(draft.mealId),s=getShop(m.shopId),q=quote(m,draft.mode,draft.size,draft.qty);nav.innerHTML='';nav.className='';app.innerHTML=topbar('把这顿安排好')+`<div class="page narrow"><div class="notice">${icon('info')}<span>演示数据，不会产生真实交易，无需支付。</span></div><div class="panel"><div class="checkout-meal">${photo(m)}<div><h3>${m.name}</h3><p>${draft.size==='large'?'加量份':'标准份'} · ${esc(draft.spicy)} · ${draft.qty} 份</p><span class="price"><small>¥</small>${money(q.goods)}</span></div></div><button class="text-link spaced" ${act('spec',`data-id="${m.id}" data-edit="yes"`)}>修改规格与数量${icon('chevron','sm')}</button></div><div class="panel"><button class="edit-row" ${act('checkout-mode')}><div><strong>怎么吃</strong><p>按你今天的状态来</p></div><span>${modes[draft.mode]}${icon('chevron','sm')}</span></button><button class="edit-row" ${act('times')}><div><strong>${draft.mode==='delivery'?'预计送达时段':'预约取餐时段'}</strong><p>自选时段，按演示容量接单</p></div><span>${esc(draft.slot)}${icon('chevron','sm')}</span></button><button class="edit-row" ${act('spot')}><div><strong>${draft.mode==='delivery'?'送达地点':'取餐地点'}</strong><p>${esc(draft.spot)}</p></div>${icon('chevron','sm')}</button><label class="field-label" for="order-note">给这顿留句话</label><textarea id="order-note" maxlength="120" placeholder="例如：少放盐、汤面分装（最多120字）" class="plain-input">${esc(draft.note)}</textarea></div><div class="panel"><h3>每一笔，算清楚</h3>${feeLines(q)}<p class="micro spaced">校外餐食满 ¥30，模拟优惠减 ¥3；包装按份计，配送按单计。</p></div><div class="notice green spaced">${icon('bag')}<span>${s.keep}。等待与送达时间为模拟，不保证真实履约。</span></div></div>`;bottomAction(q.total,'确认预约（演示）','place',`<small>已含包装与配送</small>`);}
function missingDraft(){navRender('home');app.innerHTML=topbar('确认预约')+empty('还没有选好这顿','先选一份喜欢的饭，再来安排时间。');}
function successPage(id){const o=state.orders.find(o=>o.id===id);if(!o)return notFound();navRender('orders');app.innerHTML=topbar('预约成功')+`<div class="page narrow"><div class="success"><div class="success-mark">${icon('check')}</div><span class="eyebrow">YOUR MEAL IS ON THE WAY</span><h1 style="margin-top:10px">这顿，安排好了。</h1><p>把等饭的时间，留给自己。</p></div><div class="voucher"><span class="eyebrow">你的这顿 / 预约凭证</span><h2 style="margin-top:12px">${esc(o.name)}</h2><p class="muted spaced">${modes[o.mode]} · ${esc(o.slot)}</p><p class="micro">${esc(o.spot)}</p><div class="fee-line fee-total" style="margin-top:20px"><span>到手总价</span><strong>¥${money(o.quote.total)}</strong></div></div><button class="primary full spaced" ${act('go',`data-path="/order/${o.id}"`)}>看看饭做到哪了${icon('arrow','sm')}</button><button class="secondary full spaced" ${act('home')}>继续逛逛</button><p class="micro spaced" style="text-align:center">演示预约成功，不产生真实交易</p></div>`;}
function orderPage(id){const o=state.orders.find(x=>x.id===id);if(!o)return notFound();const m=getMeal(o.mealId);navRender('orders');const stages=['placed','preparing',o.mode==='delivery'?'delivering':'ready','done'];const index=stages.indexOf(o.status);app.innerHTML=topbar('这顿的进度')+`<div class="page narrow"><div class="status-banner"><div class="row between"><h2>${statusText(o)}</h2>${icon(o.mode==='delivery'?'truck':'bowl','lg')}</div><p>${o.status==='cancelled'?'预约已取消，没有发生费用扣款。':o.status==='done'?'这顿吃好了，下顿再见。':o.delayed?'窗口正在忙，预计较原时段延后 10 分钟。':`${esc(o.slot)} ${o.mode==='delivery'?'预计送达':'按预约领取'}，不必反复等。`}</p>${o.status!=='cancelled'?`<div class="timeline">${stages.map((s,i)=>`<div class="timeline-step ${i<=index?'active':''}"><span></span>${['已预约','制作中',o.mode==='delivery'?'配送中':'待取餐','已完成'][i]}</div>`).join('')}</div>`:''}</div>${o.delayed&&!['done','cancelled'].includes(o.status)?`<div class="notice red">${icon('clock')}<span>演示延误提醒：建议稍后出发。下单后若遇延误，应以窗口更新为准。</span></div>`:''}${o.status==='ready'?`<button class="primary full" ${act('go',`data-path="/voucher/${id}"`)}>${icon('ticket')}出示取餐码 · ${esc(o.code)}</button>`:''}<div class="panel"><div class="checkout-meal">${photo(m)}<div><h3>${esc(o.name)}</h3><p>${o.size==='large'?'加量份':'标准份'} · ${esc(o.spicy)} · ${o.qty} 份</p><p>${getShop(m.shopId).name}</p></div></div><div class="edit-row"><span>用餐方式</span><strong>${modes[o.mode]}</strong></div><div class="edit-row"><span>预约时段</span><strong>${esc(o.slot)}</strong></div><div class="edit-row"><span>地点</span><strong style="font-size:12px;max-width:70%;text-align:right">${esc(o.spot)}</strong></div>${o.note?`<div class="edit-row"><span>备注</span><span>${esc(o.note)}</span></div>`:''}</div><div class="panel"><h3>费用明细</h3>${feeLines(o.quote)}<p class="micro spaced">订单编号 ${o.id}<br>创建于 ${new Date(o.created).toLocaleString('zh-CN')}</p></div><div class="stack spaced">${!['done','cancelled'].includes(o.status)?`<button class="primary full" ${act('advance',`data-id="${id}"`)}>${o.status==='ready'?'确认已取餐':o.status==='delivering'?'确认已收货':'推进演示进度'}${icon('arrow','sm')}</button>${['placed','preparing'].includes(o.status)?`<button class="secondary full" ${act('delay',`data-id="${id}"`)}>${o.delayed?'取消延误演示':'演示窗口延误'}</button>`:''}${o.status==='placed'?`<button class="danger-btn full" ${act('cancel',`data-id="${id}"`)}>取消这次预约</button>`:''}`:`${o.status==='done'?`<button class="primary full" ${act('review',`data-id="${id}"`)}>${o.rated?'查看我的评价':'评价这顿'}</button>`:''}<button class="secondary full" ${act('spec',`data-id="${m.id}"`)}>再吃一次</button>`}</div><p class="micro spaced" style="text-align:center">状态由你手动推进，用于展示流程；不代表真实接单。</p></div>`;}
function voucherPage(id){const o=state.orders.find(x=>x.id===id);if(!o)return notFound();navRender('orders');if(o.status!=='ready'){app.innerHTML=topbar('取餐凭证')+empty('当前暂不能取餐','仅待取餐的订单可以使用取餐凭证。','view-order','查看订单','ticket');const b=$('[data-action="view-order"]');b.dataset.id=id;return;}app.innerHTML=topbar('你的取餐凭证')+`<div class="page narrow"><div class="notice green">${icon('check')}<span>这顿做好了，记得趁热吃。</span></div><div class="voucher"><span class="eyebrow">ZHEDUN / PICK UP YOUR MEAL</span><h2 class="spaced">向窗口出示此页面</h2><div class="voucher-code">${esc(o.code)}</div><p>${esc(o.name)} × ${o.qty}</p><div class="code-bars" aria-hidden="true"></div><p class="micro">图形为装饰示意，不具备扫码核销能力</p><div style="border-top:1px dashed var(--line);padding-top:20px;margin-top:20px"><strong>${esc(o.spot)}</strong><p class="muted">${esc(o.slot)} · ${modes[o.mode]}</p></div></div><button class="primary full spaced" ${act('advance',`data-id="${o.id}"`)}>我已取到这顿${icon('check','sm')}</button><p class="micro spaced" style="text-align:center">仅为前端演示凭证，无法在真实食堂使用。</p></div>`;}
function mine(){navRender('mine');const spent=state.orders.filter(o=>o.status==='done').reduce((t,o)=>t+o.quote.total,0);app.innerHTML=`<div class="profile-top"><span class="eyebrow">MY LITTLE FOOD DIARY</span><div class="profile-user"><div class="avatar">${icon('bowl')}</div><div><h1>好好吃饭的同学</h1><p>日子再忙，也别亏待这顿。</p></div></div><div class="profile-stats"><button ${act('go','data-path="/favorites"')}><strong>${state.favorites.length}</strong>收藏的好饭</button><button ${act('go','data-path="/orders"')}><strong>${state.orders.filter(o=>o.status==='done').length}</strong>吃好的这几顿</button><button ${act('go','data-path="/records"')}><strong>¥${money(spent)}</strong>已完成支出</button></div></div><div class="page"><div class="notice green">${icon('leaf')}<span>默认预算 ¥${state.prefs.budget}，用餐时间 ${esc(state.prefs.usual)}。下一顿也按自己的节奏来。</span></div><div class="menu-list">${[['heart','收藏的好饭','/favorites'],['filter','我的口味与安排','/preferences'],['chart','用餐记录与支出','/records'],['order','全部订单','/orders'],['info','关于这个样品','/about']].map(([glyph,label,path])=>`<a class="menu-row" href="#${path}">${icon(glyph)}<span>${label}</span>${icon('chevron')}</a>`).join('')}<button class="menu-row" ${act('reset')}>${icon('reset')}<span>重置演示数据</span>${icon('chevron')}</button></div><p class="footnote">把每一顿，吃成小确幸</p><p class="micro" style="text-align:center">无需账号 · 数据只保存在当前浏览器</p></div>`;}
function favorites(){navRender('mine');const list=state.favorites.map(getMeal).filter(Boolean);app.innerHTML=topbar('收藏的好饭')+`<div class="page narrow"><p class="subtitle">留住喜欢的味道，下次少想一会儿。</p>${list.length?`<div class="meal-grid">${list.map(card).join('')}</div>`:empty('先收藏一份喜欢的饭','打开菜品详情，点一下右上角的收藏。','home','去找好饭','heart')}</div>`;}
function preferences(){navRender('mine');app.innerHTML=topbar('我的口味与安排')+`<div class="page narrow"><p class="subtitle">记住这些小偏好，下一顿推荐更省心。</p><form id="prefs-form"><div class="panel"><label class="field-label" for="pref-budget">每顿预算上限</label><div class="form-row"><input id="pref-budget" name="budget" type="range" min="10" max="60" step="1" value="${state.prefs.budget}"><strong id="pref-budget-value">¥${state.prefs.budget}</strong></div><label class="field-label" for="pref-minutes">通常有多少时间吃上饭</label><select class="plain-input" id="pref-minutes" name="minutes">${[15,20,30,45,60].map(n=>`<option value="${n}" ${n===state.prefs.minutes?'selected':''}>${n} 分钟以内</option>`).join('')}</select><label class="field-label" for="pref-taste">口味偏好</label><select class="plain-input" id="pref-taste" name="taste">${['all',...tastes].map(t=>`<option value="${t}" ${t===state.prefs.taste?'selected':''}>${t==='all'?'都可以':t}</option>`).join('')}</select><label class="field-label" for="pref-mode">常用用餐方式</label><select class="plain-input" id="pref-mode" name="mode">${[['all','不限方式'],...Object.entries(modes)].map(([key,text])=>`<option value="${key}" ${key===state.prefs.mode?'selected':''}>${text}</option>`).join('')}</select><label class="field-label" for="pref-time">我的用餐时间</label><input class="plain-input" id="pref-time" type="time" name="usual" value="${esc(state.prefs.usual)}" required><label class="field-label" for="pref-spot">常用宿舍取餐点</label><select class="plain-input" name="spot" id="pref-spot">${['知行宿舍楼下取餐柜','明德宿舍南门取餐点','图书馆东侧取餐柜'].map(p=>`<option ${state.prefs.spot===p?'selected':''}>${p}</option>`).join('')}</select></div><div class="notice spaced">${icon('clock')}<span>用餐时间仅作本地安排参考，首页会提示提前预约；不会发送系统通知或读取真实课表。</span></div><button class="primary full spaced" type="submit">保存我的偏好${icon('check','sm')}</button></form></div>`;}
function records(){navRender('mine');const list=state.orders.filter(o=>o.status==='done'),sum=list.reduce((n,o)=>n+o.quote.total,0),canteen=list.filter(o=>getShop(getMeal(o.mealId).shopId).type==='canteen').length;app.innerHTML=topbar('用餐记录与支出')+`<div class="page narrow"><div class="panel"><span class="eyebrow">每一顿，都算数</span><div class="budget-big"><small>¥</small>${money(sum)}</div><p class="micro">已完成模拟订单支出 · 共 ${list.length} 顿</p><div class="fee-line spaced"><span>食堂用餐</span><span>${canteen} 顿</span></div><div class="bar-track"><div class="bar-fill green" style="width:${list.length?canteen/list.length*100:0}%"></div></div><div class="fee-line"><span>校外外卖</span><span>${list.length-canteen} 顿</span></div><div class="bar-track"><div class="bar-fill" style="width:${list.length?(list.length-canteen)/list.length*100:0}%"></div></div></div><div class="section-head"><h2>吃好的这几顿</h2></div>${list.length?list.map(o=>`<a class="record-row" href="#/order/${o.id}">${photo(getMeal(o.mealId))}<div><h3 style="font-size:13px">${esc(o.name)}</h3><p>${date(o.created)} · ${modes[o.mode]}</p></div><strong>¥${money(o.quote.total)}</strong></a>`).join(''):empty('记录从下一顿开始','完成一笔模拟订单，就会出现在这里。')}<p class="micro spaced">仅统计已完成订单，不含取消和进行中的订单。此处不提供营养诊断。</p></div>`;}
function about(){navRender('mine');app.innerHTML=topbar('关于这顿')+`<div class="page narrow about-copy"><div class="brand"><img src="assets/logo.svg" alt=""><b>这顿</b></div><h1 style="font-size:28px">忙归忙，<br>这顿好好吃。</h1><p>这是一份面向大学生的移动端前端样品，探索如何在时间、预算、口味和不同生活状态之间，找到合适的一顿饭。</p><h2>你可以体验什么</h2><p>按情境选餐、比较到手价与等待时间、预约取餐、查看演示进度、收藏、评价与记录支出。下单前可以自主选择堂食、自取、取餐柜或配送。</p><h2>演示数据说明</h2><p>住宿区域采用中国传媒大学公寓名称；商家、菜品资料、评价、优惠、分量和营业能力均为虚构或模拟，住宿区域选择仅用于样品演示；食物图片由 AI 生成，仅为同类餐食示意，并非商家实际出品。图标为本项目手绘 SVG，全站不使用 Emoji。</p><h2>不会产生真实交易</h2><p>没有接入真实支付、商家、配送、食品安全检测、营养检测或跨平台比价服务。预约、取餐码和订单状态仅用于交互演示。</p><h2>数据只留在你的浏览器</h2><p>收藏、偏好和模拟订单存储于当前浏览器，不要求登录。清理浏览器数据或切换设备后，记录不会同步。可以在“我的”中重置演示数据。</p><div class="notice spaced">${icon('info')}<span>首次进入会载入少量示例记录，帮助快速体验页面。</span></div></div>`;}
function notFound(){navRender('home');app.innerHTML=topbar('页面没找到')+empty('这页暂时没找到','可能链接不完整，回首页继续找饭吧。');}
function render(){closeSheet();const live=[app,nav,dock],pos=window.scrollY;const nextPath=location.hash||'#/';const samePage=renderedPath===nextPath;if(samePage)[app,nav,dock]=live.map(el=>el.cloneNode(false));const path=(location.hash.slice(1)||'/').split('?')[0],parts=path.split('/').filter(Boolean);const key=parts[0]||'home';app.dataset.route=key;document.title=({home:'这顿 · 好好吃顿饭',meal:'看看这份饭 · 这顿',orders:'我的订单 · 这顿',decide:'这顿帮你定 · 这顿',discover:'换一口新鲜 · 这顿'}[key]||'这顿 · 校园用餐助手');const routes={home,decide:decisionPage,search:searchPage,meal:()=>mealPage(parts[1]),shop:()=>shopPage(parts[1]),compare:comparePage,discover,orders:ordersPage,checkout,success:()=>successPage(parts[1]),order:()=>orderPage(parts[1]),voucher:()=>voucherPage(parts[1]),mine,favorites,preferences,records,about};(routes[key]||notFound)();dockRender(['home','search','discover','favorites','shop'].includes(key));if(samePage){const staged=[app,nav,dock];[app,nav,dock]=live;live.forEach((el,i)=>{el.className=staged[i].className;patchChildren(el,staged[i]);});window.scrollTo(0,pos);}else window.scrollTo(0,0);renderedPath=nextPath;}
window.addEventListener('hashchange',render);
function slotsFor(m,mode,weather=filters.weather){const now=new Date();now.setMinutes(Math.ceil((now.getMinutes()+eta(m,mode,weather)+10)/10)*10,0,0);const fmt=t=>t.toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit',hour12:false});return Array.from({length:4},(_,i)=>{const start=new Date(now.getTime()+i*10*60000),end=new Date(start.getTime()+10*60000);return {label:`${fmt(start)}–${fmt(end)}`,full:i===1};});}
function defaultSpot(m,mode){return mode==='delivery'||mode==='cabinet'?state.prefs.spot:getShop(m.shopId).place;}
function openSpec(id,mode,edit=false,weather=filters.weather){const m=getMeal(id);if(!m)return;if(m.sold){toast('这份饭今天售罄了，看看其他菜吧');return;}let chosen=mode||currentMode();if(!m.modes.includes(chosen)){toast('这份餐食不支持当前方式，请换一种');return;}submitting=false;const work=edit&&draft?.mealId===id?{...draft}:{mealId:id,mode:chosen,weather,size:'standard',qty:1,spicy:'正常',slot:slotsFor(m,chosen,weather)[0].label,spot:defaultSpot(m,chosen),note:''};openSheet({type:'spec',work,edit});}
function openSheet(data){lastFocus=document.activeElement;sheetState=data;document.body.style.overflow='hidden';renderSheet();requestAnimationFrame(()=>$('#modal-root button')?.focus());}
function closeSheet(){if(!sheetState)return;sheetState=null;$('#modal-root').innerHTML='';document.body.style.overflow='';if(lastFocus?.isConnected)lastFocus.focus({preventScroll:true});}
function sheetChoice(key,value,text,active,disabled=false,sub=''){return `<button type="button" class="choice ${active?'active':''}" ${act('sheet-choice',`data-key="${key}" data-value="${esc(value)}"`)} ${disabled?'disabled':''}>${text}${sub?`<small>${sub}</small>`:''}</button>`;}
function modeChoices(m,selected){return `<div class="mode-grid">${m.modes.map(mode=>`<button class="mode-opt ${selected===mode?'active':''}" ${act('sheet-mode',`data-value="${mode}"`)}>${icon(modeIcon(mode),'sm')}${modes[mode]}</button>`).join('')}</div>`;}
function renderSheet(){if(!sheetState)return;const st=sheetState;let title='',body='';
 if(st.type==='campus'){title='选择住宿区域';body=`<p class="subtitle">选择你所在的公寓，下次打开会记住。</p><div class="residence-list" role="radiogroup" aria-label="住宿区域">${residences.map((name,i)=>`<button type="button" role="radio" aria-checked="${state.prefs.campus===name}" class="residence-option ${state.prefs.campus===name?'active':''}" ${act('select-campus',`data-value="${name}"`)}><span class="residence-marker">${icon('pin')}</span><span class="residence-option-copy"><span class="residence-university">中国传媒大学</span><strong>${name.replace('中国传媒大学','')}</strong>${i===0?'<small>默认住宿区域</small>':''}</span><span class="residence-check">${icon(state.prefs.campus===name?'check':'chevron','sm')}</span></button>`).join('')}</div>`;}
 if(st.type==='filter'){const p=st.work;title='这顿，你来定';body=`<p class="subtitle">留一点时间和预算，给喜欢的饭。</p><label class="field-label" for="filter-budget">到手预算上限</label><div class="form-row"><input type="range" id="filter-budget" min="8" max="60" value="${p.budget}"><strong id="filter-budget-value">¥${p.budget}</strong></div><div class="range-caption"><span>¥8</span><span>¥60</span></div><span class="field-label">多久之内吃上饭</span><div class="choices">${[15,20,30,45,60].map(v=>sheetChoice('minutes',v,v+'分钟',Number(p.minutes)===v)).join('')}</div><span class="field-label">怎么吃</span><div class="choices">${[['all','都可以'],...Object.entries(modes)].map(([v,label])=>sheetChoice('mode',v,label,p.mode===v)).join('')}</div><span class="field-label">今天的口味</span><div class="choices">${['all',...tastes].map(v=>sheetChoice('taste',v,v==='all'?'都可以':v,p.taste===v)).join('')}</div><span class="field-label">今天的精力</span><div class="choices">${sheetChoice('energy','normal','愿意走走',p.energy==='normal')}${sheetChoice('energy','low','想少折腾',p.energy==='low')}</div><p class="micro spaced">想少折腾时，优先考虑配送；最终方式仍由你选择。</p><div class="sheet-footer"><p class="filter-match-count" id="filter-match-count" aria-live="polite">匹配 ${previewMatches().length} 道 · 可预约 ${previewMatches().filter(m=>!m.sold).length} 道</p><button class="primary full" ${act('apply-filter')}>看看合适的饭<span id="filter-apply-count">（${previewMatches().length} 道）</span>${icon('arrow','sm')}</button></div>`;}
 if(st.type==='spec'){const d=st.work,m=getMeal(d.mealId),q=quote(m,d.mode,d.size,d.qty);title='这份饭，按你喜欢的来';body=`<div class="checkout-meal">${photo(m)}<div><h3>${m.name}</h3><p>${m.portion}</p><strong class="price"><small>¥</small>${money(q.total)}</strong><small class="muted"> 到手价</small></div></div><span class="field-label">份量</span><div class="choices">${sheetChoice('size','standard','标准份',d.size==='standard',false,'日常刚刚好')}${sheetChoice('size','large','加量份',d.size==='large',false,'主食加量 +¥3 / 份')}</div><span class="field-label">口味备注</span><div class="choices">${['正常','少辣','不辣'].map(v=>sheetChoice('spicy',v,v,d.spicy===v)).join('')}</div><p class="micro spaced">备注用于演示，不代表所有菜品均可实际调整。</p><span class="field-label">用餐方式</span>${modeChoices(m,d.mode)}<div class="form-row spaced"><strong>数量</strong><div class="quantity"><button aria-label="减少一份" ${act('qty','data-delta="-1"')} ${d.qty<=1?'disabled':''}>${icon('minus')}</button><strong>${d.qty}</strong><button aria-label="增加一份" ${act('qty','data-delta="1"')} ${d.qty>=5?'disabled':''}>${icon('plus')}</button></div></div><div class="fee-line"><span>餐食 ¥${money(q.goods)} + 包装 ¥${money(q.pack)} + 配送 ¥${money(q.delivery)}</span></div>${q.discount?`<p class="micro" style="color:var(--green)">已满足餐食满 30 减 3，优惠 ¥3</p>`:''}<div class="sheet-footer"><button class="primary full" ${act('confirm-spec')}>${st.edit?'保存修改':'去预约这顿'} · ¥${money(q.total)}${icon('arrow','sm')}</button></div>`;}
 if(st.type==='mode'){title='这顿，在哪里吃';body=`${modeChoices(getMeal(draft.mealId),st.work.mode)}<p class="micro spaced">改变方式后，会重新计算费用和可用时段。</p><div class="sheet-footer"><button class="primary full" ${act('confirm-mode')}>确认用餐方式</button></div>`;}
 if(st.type==='times'){title=draft.mode==='delivery'?'选一个送达时段':'选一个取餐时段';body=`<div class="notice">${icon('clock')}<span>按当前时间生成演示时段，第二个时段模拟约满。</span></div><div class="choices spaced">${st.slots.map(s=>sheetChoice('slot',s.label,s.label,st.work.slot===s.label,s.full,s.full?'该时段约满':'可预约')).join('')}</div><div class="sheet-footer"><button class="primary full" ${act('confirm-time')}>就这个时间</button></div>`;}
 if(st.type==='spot'){title=draft.mode==='delivery'?'选择送达地点':'选择取餐地点';const m=getMeal(draft.mealId);const options=draft.mode==='delivery'||draft.mode==='cabinet'?['知行宿舍楼下取餐柜','明德宿舍南门取餐点','图书馆东侧取餐柜']:[getShop(m.shopId).place];body=`<p class="subtitle">以下均为虚构校园的示例地点。</p><div class="stack">${options.map(p=>sheetChoice('spot',p,p,st.work.spot===p)).join('')}</div><div class="sheet-footer"><button class="primary full" ${act('confirm-spot')}>确认地点</button></div>`;}
 if(st.type==='review'){const o=state.orders.find(x=>x.id===st.id);title=o.rated?'我的这顿评价':'这顿，吃得怎么样';body=`<p class="subtitle">${esc(o.name)}</p><div class="rating-pick" aria-label="评分">${[1,2,3,4,5].map(n=>`<button class="${n<=st.rating?'on':''}" aria-label="${n}分" ${act('rating',`data-value="${n}"`)} ${o.rated?'disabled':''}>${icon('star')}</button>`).join('')}</div><p class="micro">${st.rating} / 5 分</p><label class="field-label" for="review-text">说点具体的，更能帮到下一位同学</label><textarea class="plain-input" id="review-text" maxlength="200" placeholder="分量、咸淡、打包口感怎么样？" ${o.rated?'readonly':''}>${esc(st.text)}</textarea><p class="micro spaced">评价仅保存在本浏览器，不会发布给真实商家。</p><div class="sheet-footer"><button class="primary full" ${act(o.rated?'close':'submit-review')}>${o.rated?'知道了':'保存这顿评价'}</button></div>`;}
 if(st.type==='reset'){title='重新开始体验';body=`<p class="detail-desc">将清除当前浏览器中的收藏、偏好、模拟订单和评价，并恢复首次进入时的示例记录。</p><div class="stack spaced"><button class="danger-btn full" ${act('confirm-reset')}>重置演示数据</button><button class="secondary full" ${act('close')}>保留当前记录</button></div>`;}
 if(st.type==='cancel'){title='取消这次预约？';body=`<p class="detail-desc">这顿还没有开始制作，可以取消。演示预约未产生扣款。</p><div class="stack spaced"><button class="danger-btn full" ${act('confirm-cancel',`data-id="${st.id}"`)}>确认取消</button><button class="secondary full" ${act('close')}>继续等这顿</button></div>`;}
 patchHTML($('#modal-root'),`<div class="overlay" data-overlay><section class="sheet" role="dialog" aria-modal="true" aria-labelledby="sheet-title"><div class="handle"></div><div class="sheet-head"><h2 id="sheet-title">${title}</h2><button class="icon-btn close" aria-label="关闭弹层" ${act('close')}>${icon('close')}</button></div>${body}</section></div>`);}
const actions={
 'decision-start':()=>{ensureDecision();go('/decide');},
 'decision-next':()=>{ensureDecision().step=Math.min(3,decisionSession.step+1);decisionRefresh();},
 'decision-prev':()=>{ensureDecision().step=Math.max(1,decisionSession.step-1);decisionRefresh();},
 'decision-choice':el=>{const session=ensureDecision(),key=el.dataset.key;const next={...session.conditions,[key]:key==='minutes'?Number(el.dataset.value):el.dataset.value};if(!validConditions(next))return;session.conditions=next;rememberDecision();render();},
 'decision-result':()=>{const session=ensureDecision();session.complete=true;session.result=decide(session.conditions);decisionRefresh();},
 'decision-edit':()=>{const session=ensureDecision();session.complete=false;session.step=1;decisionRefresh();},
 'decision-new':()=>{decisionSession={version:1,conditions:decisionDefaults(filters),step:1,complete:false};decisionRefresh();},
 'decision-relax':el=>{const session=ensureDecision();const suggestion=decide(session.conditions).suggestions.find(s=>s.key===el.dataset.key&&s.value===Number(el.dataset.value));if(!suggestion)return;session.conditions[suggestion.key]=suggestion.value;session.result=decide(session.conditions);decisionRefresh();toast(suggestion.key==='budget'?'预算已调整至 ¥'+suggestion.value:'可用时间已调整为 '+suggestion.value+' 分钟');},
 go:el=>go(el.dataset.path),home:()=>go('/'),back,close:closeSheet,
 campus:()=>openSheet({type:'campus'}),
 'select-campus':el=>{const campus=el.dataset.value;if(!residences.includes(campus))return;state.prefs.campus=campus;filters.campus=campus;persist();closeSheet();render();toast('已切换至'+campus.replace('中国传媒大学',''));},
 weather:()=>{filters.weather=filters.weather==='sun'?'rain':'sun';render();toast(filters.weather==='rain'?'已切到雨天情境，配送估计增加5分钟':'已切到晴天情境');},
 scenario:el=>{const v=el.dataset.value;scenario=scenario===v?'':v;homeLimit=8;filters={...filters,mode:scenario==='dorm'?'delivery':'all',minutes:scenario==='rush'?20:45,budget:scenario==='save'?18:30};render();},
 filter:()=>openSheet({type:'filter',work:{...filters}}),
 'apply-filter':()=>{filters={...sheetState.work};scenario='';homeLimit=8;if(filters.energy==='low'&&filters.mode==='all')filters.mode='delivery';closeSheet();render();toast('已按你的条件重新选餐');},
 'reset-filter':()=>{homeLimit=8;filters=defaultPrefs();scenario='';render();},
 'reset-search':()=>{homeLimit=8;filters=defaultPrefs();scenario='';query='';kind='all';sort='smart';render();},
 kind:el=>{kind=el.dataset.value;render();},
 compare:el=>{const id=el.dataset.id;if(compare.includes(id))compare=compare.filter(x=>x!==id);else if(compare.length===3){toast('最多比较三份餐食，先移出一份吧');return;}else compare.push(id);const pos=scrollY;render();scrollTo(0,pos);toast(compare.includes(id)?'已加入比较':'已移出比较');},
 'clear-compare':()=>{compare=[];const pos=scrollY;render();scrollTo(0,pos);},
 'compare-mode':el=>{filters.mode=el.dataset.value;render();},
 favorite:el=>{const id=el.dataset.id;if(state.favorites.includes(id))state.favorites=state.favorites.filter(x=>x!==id);else state.favorites.push(id);persist();const pos=scrollY;render();scrollTo(0,pos);toast(state.favorites.includes(id)?'这份好饭，收藏好了':'已取消收藏');},
 spec:el=>openSpec(el.dataset.id,el.dataset.mode,el.dataset.edit==='yes',el.dataset.weather||filters.weather),sold:()=>toast('这份饭今天已售罄，可以看看同窗口其他餐食'),
 qty:el=>{sheetState.work.qty=Math.max(1,Math.min(5,sheetState.work.qty+Number(el.dataset.delta)));renderSheet();},
 'sheet-choice':el=>{if(!sheetState?.work)return;const k=el.dataset.key,v=el.dataset.value;sheetState.work[k]=k==='minutes'?Number(v):v;renderSheet();},
 'sheet-mode':el=>{const d=sheetState.work;d.mode=el.dataset.value;const m=getMeal(d.mealId||draft.mealId);d.spot=defaultSpot(m,d.mode);d.slot=slotsFor(m,d.mode,d.weather||filters.weather)[0].label;renderSheet();},
 'confirm-spec':()=>{draft={...sheetState.work};saveDraft();closeSheet();go('/checkout');},
 'checkout-mode':()=>openSheet({type:'mode',work:{...draft}}),
 'confirm-mode':()=>{draft={...sheetState.work};saveDraft();closeSheet();render();},
 times:()=>{const slots=slotsFor(getMeal(draft.mealId),draft.mode,draft.weather||filters.weather);const slot=slots.some(s=>s.label===draft.slot&&!s.full)?draft.slot:slots[0].label;openSheet({type:'times',slots,work:{slot}});},
 'confirm-time':()=>{if(sheetState.slots.some(s=>s.label===sheetState.work.slot&&!s.full)){draft.slot=sheetState.work.slot;saveDraft();closeSheet();render();}},
 spot:()=>openSheet({type:'spot',work:{spot:draft.spot}}),
 'confirm-spot':()=>{draft.spot=sheetState.work.spot;saveDraft();closeSheet();render();},
 place:()=>{if(submitting||!draft)return;const m=getMeal(draft.mealId);if(!m||m.sold){toast('这份饭暂时无法预约');return;}if(!m.modes.includes(draft.mode)||draft.qty<1||draft.qty>5||!draft.slot){toast('请重新确认规格、时间与用餐方式');return;}submitting=true;draft.note=$('#order-note')?.value||draft.note;const id='ZD'+Date.now().toString(36).toUpperCase()+Math.random().toString(36).slice(2,5).toUpperCase();const order={...draft,id,name:m.name,quote:quote(m,draft.mode,draft.size,draft.qty),status:'placed',delayed:false,created:Date.now(),code:String(Math.floor(1000+Math.random()*9000)),rated:false};state.orders.unshift(order);persist();draft=null;saveDraft();go('/success/'+id);},
 'order-tab':el=>{orderTab=el.dataset.value;render();},
 'view-order':el=>go('/order/'+el.dataset.id),
 advance:el=>{const o=state.orders.find(x=>x.id===el.dataset.id);if(!o)return;const next={placed:'preparing',preparing:o.mode==='delivery'?'delivering':'ready',ready:'done',delivering:'done'}[o.status];if(!next)return;o.status=next;o.delayed=false;persist();if(location.hash.includes('/voucher/'))go('/order/'+o.id);else render();toast(next==='done'?'这顿吃好了，记得给个评价':'演示状态已更新');},
 delay:el=>{const o=state.orders.find(x=>x.id===el.dataset.id);if(!o||!['placed','preparing'].includes(o.status))return;o.delayed=!o.delayed;persist();render();},
 cancel:el=>openSheet({type:'cancel',id:el.dataset.id}),
 'confirm-cancel':el=>{const o=state.orders.find(x=>x.id===el.dataset.id);if(!o||o.status!=='placed')return;o.status='cancelled';persist();closeSheet();render();toast('预约已取消');},
 'discover-taste':el=>{discoverTaste=el.dataset.value;discoverLimit=12;render();},
 'home-more':()=>{const pos=scrollY;homeLimit+=8;render();scrollTo(0,pos);},
 'discover-more':()=>{const pos=scrollY;discoverLimit+=12;render();scrollTo(0,pos);},
 review:el=>{const o=state.orders.find(x=>x.id===el.dataset.id);if(!o||o.status!=='done')return;const r=state.reviews.find(x=>x.orderId===o.id);openSheet({type:'review',id:o.id,rating:r?.rating||5,text:r?.text||''});},
 rating:el=>{sheetState.rating=Number(el.dataset.value);renderSheet();},
 'submit-review':()=>{const o=state.orders.find(x=>x.id===sheetState.id);if(!o||o.rated)return;state.reviews.push({orderId:o.id,mealId:o.mealId,rating:sheetState.rating,text:sheetState.text||'',created:Date.now()});o.rated=true;persist();closeSheet();render();toast('已保存，谢谢你认真吃好这一顿');},
 reset:()=>openSheet({type:'reset'}),
 'confirm-reset':()=>{homeLimit=8;discoverLimit=12;state=seed();filters={...state.prefs};compare=[];scenario='';query='';kind='all';sort='smart';orderTab='all';draft=null;decisionSession=null;try{decisionStorage()?.removeItem(DECISION_KEY);}catch{}saveDraft();persist();closeSheet();render();toast('已恢复初始演示数据');}
};
document.addEventListener('click',e=>{if(e.target.matches('[data-overlay]')){closeSheet();return;}const el=e.target.closest('[data-action]');if(!el||el.disabled)return;e.preventDefault();actions[el.dataset.action]?.(el);});
document.addEventListener('input',e=>{const el=e.target;if(el.id==='decision-budget'){const session=ensureDecision();session.conditions.budget=Number(el.value);$('#decision-budget-value').textContent=el.value;rememberDecision();}if(el.id==='filter-budget'){sheetState.work.budget=Number(el.value);$('#filter-budget-value').textContent='¥'+el.value;updateFilterCount();}if(el.id==='pref-budget')$('#pref-budget-value').textContent='¥'+el.value;if(el.id==='review-text'&&sheetState)sheetState.text=el.value;if(el.id==='order-note'&&draft){draft.note=el.value;saveDraft();}});
document.addEventListener('change',e=>{if(e.target.id==='sort'){sort=e.target.value;scenario='';render();}});
document.addEventListener('submit',e=>{if(e.target.id==='search-form'){e.preventDefault();query=new FormData(e.target).get('q').trim();render();}if(e.target.id==='prefs-form'){e.preventDefault();const f=new FormData(e.target);state.prefs={...state.prefs,budget:Number(f.get('budget')),minutes:Number(f.get('minutes')),taste:f.get('taste'),mode:f.get('mode'),usual:f.get('usual'),spot:f.get('spot')};filters={...state.prefs};persist();toast('偏好记好了，下一顿按你的节奏来');go('/mine');}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeSheet();if(e.key==='Tab'&&sheetState){const focusable=[...$('#modal-root').querySelectorAll('button:not(:disabled),input,textarea,select,a[href]')].filter(el=>!el.hidden);const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
document.addEventListener('error',e=>{if(e.target.tagName!=='IMG')return;const img=e.target;if(img.dataset.failed)return;img.dataset.failed='yes';const parent=img.parentElement;if(parent.classList.contains('meal-photo')||parent.classList.contains('detail-hero')||parent.classList.contains('hero')){const fallback=document.createElement('span');fallback.className='image-fallback';fallback.innerHTML=icon('bowl')+'<span>图片暂时没端上来</span>';parent.append(fallback);}else{img.style.background='#eadbc3';img.alt='图片暂时无法显示';}},true);
render();
